// Compass abbreviations per language: N E S W.
const _compass = <String, List<String>>{
  'ar': ['ش', 'ق', 'ج', 'غ'],
  'fr': ['N', 'E', 'S', 'O'],
  'es': ['N', 'E', 'S', 'O'],
  'de': ['N', 'O', 'S', 'W'],
  'tr': ['K', 'D', 'G', 'B'],
  'ur': ['ش', 'م', 'ج', 'غ'],
  'id': ['U', 'T', 'S', 'B'],
  'ms': ['U', 'T', 'S', 'B'],
  'hi': ['उ', 'पू', 'द', 'प'],
  'bn': ['উ', 'পূ', 'দ', 'প'],
  'fa': ['ش', 'ر', 'ج', 'غ'],
  'ru': ['С', 'В', 'Ю', 'З'],
  'zh': ['北', '东', '南', '西'],
  'sw': ['Ka', 'Ma', 'Ku', 'Mg'],
};

/// "NE" -> localized compass abbreviation (e.g. "ش ق", "СВ", "东北").
String compassWord(String lang, String code) {
  final t = _compass[lang];
  if (t == null || !RegExp(r'^[NESW]{1,3}$').hasMatch(code)) return code;
  final letters = code.split('').map((c) => t['NESW'.indexOf(c)]).toList();
  if (lang == 'zh') {
    if (code.length == 3) {
      // NNE -> 北东北, ENE -> 东北东 (dominant, other, dominant).
      final x = code[0];
      final other = code[1] != x ? code[1] : code[2];
      return t['NESW'.indexOf(x)] + t['NESW'.indexOf(other)] + t['NESW'.indexOf(x)];
    }
    // NE -> 东北 (the Chinese order puts E/W before N/S for the diagonal).
    return letters.reversed.join();
  }
  return letters.join(lang == 'ar' || lang == 'ur' || lang == 'fa' ? ' ' : '');
}

