String translateExtraDynamic(String lang, String text) {
  final i = _order.indexOf(lang);
  if (i < 0) return text;
  var m = RegExp(r'^(.+?) devices may silence scheduled reminders to save battery\. Look for .Battery. or .Background activity. in this app.s system settings and remove restrictions\.$').firstMatch(text);
  if (m != null) return _batteryTpl[i].replaceAll('{m}', m.group(1)!);
  m = RegExp(r'^Alarm permission: (.+)$').firstMatch(text);
  if (m != null) return _permStatusTpl[i].replaceAll('{s}', m.group(1)!);
  m = RegExp(r'^No offline match for "(.*)"\.$').firstMatch(text);
  if (m != null) return _noMatchTpl[i].replaceAll('{q}', m.group(1)!);
  m = RegExp(r'^(.+) will stay closed until you answer or decline\.$').firstMatch(text);
  if (m != null) return _guardTpl[i].replaceAll('{a}', m.group(1)!);
  m = RegExp(r'^e\.g\. (.+)$').firstMatch(text);
  if (m != null) return '${_egWord[i]} ${m.group(1)}';
  if (RegExp(r'^[NESW]{1,3}$').hasMatch(text)) return compassWord(lang, text);
  return text;
}
